import { Link, useNavigate } from 'react-router-dom';

function Navbar({ isLoggedIn, setIsLoggedIn }) {
  const navigate = useNavigate();

  const handleProtectedNav = (path) => {
    if (!isLoggedIn) {
      alert('Please login or register to access this feature');
      navigate('/login');
    } else {
      navigate(path);
    }
  };

  const handleLogout = () => {
    const confirmLogout = window.confirm('Are you sure you want to logout?');
    if (confirmLogout) {
      setIsLoggedIn(false);
      navigate('/');
    }
  };


  return (
    <div>
      <Link to="/">Home</Link> |{" "}

      <button onClick={() => handleProtectedNav('/feed')}>Feed</button>{" | "}
      <button onClick={() => handleProtectedNav('/events')}>Events</button>{" | "}
      <button onClick={() => handleProtectedNav('/chat')}>Chat</button>{" | "}

      {isLoggedIn ? (
        <button onClick={handleLogout}>Logout</button>
      ) : (
        <>
          <Link to="/login">Login</Link>{" | "}
          <Link to="/register">Register</Link>
        </>
      )}

      <hr />
    </div>
  );
}

export default Navbar;
